def describe(trait):
    t = " ".join(str(trait or "").split()).strip().rstrip(",")
    if not t:
        return None
    if t in EXACT:
        return EXACT[t]
    for prefix, d in PREFIX:
        if t.startswith(prefix) or prefix in t:
            return d
    return None
